abstract class Animal {
    String name;

    Animal(String name) {
        this.name = name;
    }

    abstract void speak();

    void sleep() {
        System.out.println(name + "睡着了，呼噜呼噜");
    }
}

class Dog extends Animal {
    Dog(String name) {
        super(name);
    }

    @Override
    void speak() {
        System.out.println(name + "：汪！");
    }
}

public class Main {
    public static void main(String[] args) {
        Animal[] pets = { new Dog("大黄") };
        for (Animal pet : pets) {
            pet.speak();
            pet.sleep();
        }
    }
}

class Animal {
    String name;

    Animal(String name) {
        this.name = name;
    }

    void speak() {
        System.out.println(name + "发出了一声叫");
    }
}

class Cat extends Animal {
    Cat(String name) {
        super(name);
    }

    void sleep() {
        System.out.println(name + "睡着了");
    }
}

public class Main {
    public static void main(String[] args) {
        Animal a = new Cat("小橘");
        if (a instanceof Cat) {
            Cat c = (Cat) a;
            c.sleep();
        }
    }
}
